using System.Text.Json;
namespace RealmGate.Server;
public sealed record RuntimeOfflineMessagingSmokeReport(bool Passed,IReadOnlyList<string> Checks,IReadOnlyList<string> Failures){public string ToJson()=>JsonSerializer.Serialize(this,new JsonSerializerOptions{WriteIndented=true});public static RuntimeOfflineMessagingSmokeReport Run(){var c=new List<string>();var f=new List<string>();void Check(bool x,string n){c.Add(n);if(!x)f.Add(n);}var now=DateTimeOffset.Parse("2026-01-01T00:00:00Z");var s=new RuntimeOfflineMessagingService(new(80,2000,10,TimeSpan.FromDays(30),false,false,false,true));Check(!s.Queue("m0",RuntimeOfflineMessageKind.PlayerMail,"alice","bob","s","b",Array.Empty<RuntimeOfflineAttachment>(),now).Accepted,"player-mail-host-boundary");var q=s.Queue("m1",RuntimeOfflineMessageKind.OfflineTell,"alice","bob","","hello",Array.Empty<RuntimeOfflineAttachment>(),now);Check(q.Accepted,"queue-offline-tell");Check(!s.Deliver("m1","mallory",now).Accepted,"recipient-authorization");Check(s.Deliver("m1","bob",now).Accepted,"deliver");Check(s.MarkRead("m1","bob").Accepted,"read");Check(s.Inbox("bob").Count==1,"inbox");Check(s.Delete("m1","bob").Accepted,"delete");Check(!s.Queue("m2",RuntimeOfflineMessageKind.AdministrativeMail,"alice","bob","notice","x",Array.Empty<RuntimeOfflineAttachment>(),now).Accepted,"admin-permission");var q2=s.Queue("m3",RuntimeOfflineMessageKind.SystemMail,null,"bob","notice","x",Array.Empty<RuntimeOfflineAttachment>(),now);Check(q2.Accepted,"system-mail");Check(s.Expire(now.AddDays(31)).Count==1,"expiration");Check(s.ValidateState().Count==0,"state-invariants");return new(f.Count==0,c,f);}}
